"use client";

import * as React from "react";
import * as stylex from "@stylexjs/stylex";
import { Field as BaseField } from "@base-ui/react/field";

import { mergeClassName } from "../shared/merge-class-name.js";
import { styles } from "./text-field.stylex.js";

export const TextFieldRoot = React.forwardRef<HTMLDivElement, BaseField.Root.Props>(
  function TextFieldRoot({ className, ...props }, ref) {
    return (
      <BaseField.Root
        {...props}
        className={mergeClassName(stylex.props(styles.root).className, className)}
        data-slot="text-field"
        ref={ref}
      />
    );
  },
);

export const TextFieldLabel = React.forwardRef<HTMLLabelElement, BaseField.Label.Props>(
  function TextFieldLabel({ className, ...props }, ref) {
    return (
      <BaseField.Label
        {...props}
        className={mergeClassName(stylex.props(styles.label).className, className)}
        data-slot="text-field-label"
        ref={ref}
      />
    );
  },
);

export const TextFieldControl = React.forwardRef<HTMLElement, BaseField.Control.Props>(
  function TextFieldControl({ className, ...props }, ref) {
    return (
      <BaseField.Control
        {...props}
        className={mergeClassName(stylex.props(styles.control).className, className)}
        data-slot="text-field-control"
        ref={ref}
      />
    );
  },
);

export const TextFieldDescription = React.forwardRef<HTMLDivElement, BaseField.Description.Props>(
  function TextFieldDescription({ className, ...props }, ref) {
    return (
      <BaseField.Description
        {...props}
        className={mergeClassName(stylex.props(styles.description).className, className)}
        data-slot="text-field-description"
        ref={ref}
      />
    );
  },
);

export const TextFieldError = React.forwardRef<HTMLDivElement, BaseField.Error.Props>(
  function TextFieldError({ className, ...props }, ref) {
    return (
      <BaseField.Error
        {...props}
        className={mergeClassName(stylex.props(styles.error).className, className)}
        data-slot="text-field-error"
        ref={ref}
      />
    );
  },
);

export const TextField = {
  Control: TextFieldControl,
  Description: TextFieldDescription,
  Error: TextFieldError,
  Label: TextFieldLabel,
  Root: TextFieldRoot,
} as const;

import * as stylex from "@stylexjs/stylex";

import { tokens } from "../tokens.stylex.js";

export const styles = stylex.create({
  root: {
    display: "flex",
    flexDirection: "column",
    gap: tokens.space2,
    maxWidth: "304px",
    width: "100%",
  },
  label: {
    color: tokens.colorContentPrimary,
    fontFamily: tokens.fontSans,
    fontSize: "13px",
    fontWeight: 500,
    lineHeight: "16px",
  },
  control: {
    backgroundColor: {
      default: tokens.colorSurfaceSurface,
      ":disabled": tokens.colorSurfaceInteractive,
      ":read-only": tokens.colorSurfaceReadOnly,
    },
    borderColor: {
      default: tokens.colorBorderSecondary,
      ":hover": tokens.colorBorderPrimary,
      "[data-invalid]": tokens.colorStatusErrorBorder,
      ":disabled": tokens.colorBorderTertiary,
    },
    borderRadius: tokens.radiusControl,
    borderStyle: "solid",
    borderWidth: tokens.sizeBorderControl,
    boxSizing: "border-box",
    color: tokens.colorContentPrimary,
    fontFamily: tokens.fontSans,
    fontSize: "13px",
    height: tokens.sizeInputDefault,
    lineHeight: "16px",
    outlineColor: {
      default: "transparent",
      ":focus-visible": tokens.colorFocusRing,
    },
    outlineOffset: "0px",
    outlineStyle: "solid",
    outlineWidth: {
      default: 0,
      ":focus-visible": "1px",
    },
    paddingBlock: "6px",
    paddingInline: tokens.space3,
    width: "100%",
    "::placeholder": { color: tokens.colorContentTertiary },
  },
  description: {
    color: tokens.colorContentTertiary,
    fontFamily: tokens.fontSans,
    fontSize: "12px",
    lineHeight: "16px",
  },
  error: {
    color: tokens.colorStatusErrorContent,
    fontFamily: tokens.fontSans,
    fontSize: "12px",
    lineHeight: "16px",
  },
});

export type ClassName<State> = string | ((state: State) => string | undefined);

export function mergeClassName<State>(
  generated?: string,
  className?: ClassName<State>,
): ClassName<State> {
  if (typeof className === "function") {
    return (state) => [generated, className(state)].filter(Boolean).join(" ");
  }
  return [generated, className].filter(Boolean).join(" ");
}
